import React from "react";

function Skills() {
  return (
    <div>
      <h1>Skills</h1>

      <ul>
        <li>Python</li>
        <li>SQL</li>
        <li>Java</li>
        <li>HTML</li>
        <li>CSS</li>
        <li>React</li>
      </ul>
    </div>
  );
}

export default Skills;
